from flask import Flask, request, jsonify
import hmac
import hashlib
import os
from functools import wraps

app = Flask(__name__)

# 从环境变量获取密钥
WEBHOOK_SECRET = os.environ.get('WEBHOOK_SECRET', 'whsec_default_key')

def verify_signature(payload, signature):
    """验证 webhook 签名"""
    if not signature:
        return False

    # 计算预期的签名
    expected_signature = hmac.new(
        WEBHOOK_SECRET.encode('utf-8'),
        payload,
        hashlib.sha256
    ).hexdigest()

    # 使用常量时间比较防止时序攻击
    return hmac.compare_digest(expected_signature, signature)

@app.route('/webhook', methods=['POST'])
def webhook():
    """处理 webhook 请求"""
    # 获取签名
    signature = request.headers.get('X-Hub-Signature-256')

    # 验证签名
    if not verify_signature(request.data, signature):
        return jsonify(error="Invalid signature"), 401

    # 获取事件类型
    event_type = request.headers.get('X-GitHub-Event', 'unknown')
    payload = request.get_json()

    # 根据事件类型处理
    if event_type == 'push':
        return handle_push(payload)
    elif event_type == 'pull_request':
        return handle_pull_request(payload)
    elif event_type == 'issues':
        return handle_issues(payload)
    else:
        return jsonify(message=f"Unhandled event type: {event_type}"), 200

def handle_push(payload):
    """处理 push 事件"""
    ref = payload.get('ref')
    repo = payload.get('repository', {}).get('full_name', 'unknown')

    return jsonify(
        message=f"Received push event for {ref} in {repo}",
        ref=ref,
        repo=repo
    )

def handle_pull_request(payload):
    """处理 pull request 事件"""
    action = payload.get('action')
    number = payload.get('number')
    repo = payload.get('repository', {}).get('full_name', 'unknown')

    if action == 'opened':
        return jsonify(message=f"Pull request #{number} opened in {repo}")
    elif action == 'closed':
        return jsonify(message=f"Pull request #{number} closed in {repo}")
    else:
        return jsonify(message=f"Pull request action: {action} in {repo}")

def handle_issues(payload):
    """处理 issues 事件"""
    action = payload.get('action')
    number = payload.get('number')
    repo = payload.get('repository', {}).get('full_name', 'unknown')

    return jsonify(
        message=f"Issue #{number} {action} in {repo}",
        action=action,
        number=number
    )

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
EOF

