from flask import Flask, jsonify, request, g
import os
import logging
from datetime import datetime
from functools import wraps

# 配置日志
logging.basicConfig(
    level=logging.DEBUG if os.getenv('DEBUG_MODE') == 'true' else logging.INFO,
    format='%(asctime)s - %(name)s - %(levelname)s - %(message)s'
)
logger = logging.getLogger(__name__)

app = Flask(__name__)

# 从环境变量或配置文件加载调试模式
DEBUG_MODE = os.getenv('DEBUG_MODE', 'false').lower() == 'true'

# 调试模式下的详细配置
DEBUG_CONFIG = {
    'show_headers': DEBUG_MODE,
    'show_body': DEBUG_MODE,
    'detailed_errors': DEBUG_MODE,
    'request_logging': DEBUG_MODE
}

@app.before_request
def before_request():
    """记录请求信息（调试模式下）"""
    if DEBUG_CONFIG['request_logging']:
        g.start_time = datetime.now()
        logger.debug(f"Request: {request.method} {request.path}")
        if DEBUG_CONFIG['show_headers']:
            logger.debug(f"Headers: {dict(request.headers)}")
        if DEBUG_CONFIG['show_body'] and request.method in ['POST', 'PUT', 'PATCH']:
            logger.debug(f"Body: {request.get_data()}")

@app.after_request
def after_request(response):
    """记录响应信息（调试模式下）"""
    if DEBUG_CONFIG['request_logging']:
        g.duration = (datetime.now() - g.start_time).total_seconds()
        logger.debug(f"Response: {response.status_code} in {g.duration:.4f}s")
    return response

@app.errorhandler(Exception)
def handle_exception(e):
    """统一异常处理（调试模式下显示详细信息）"""
    if DEBUG_MODE:
        logger.error(f"Unhandled exception: {type(e).__name__}: {str(e)}")
        return jsonify(
            error=str(e),
            type=type(e).__name__,
            traceback=str(e.__traceback__)
        ), 500
    return jsonify(error="Internal server error"), 500

@app.errorhandler(404)
def not_found(e):
    if DEBUG_MODE:
        return jsonify(error="Not found", path=request.path), 404
    return jsonify(error="Not found"), 404

@app.route('/debug')
def debug():
    """调试端点 - 显示当前配置和系统信息"""
    return jsonify({
        'debug_mode': DEBUG_MODE,
        'config': DEBUG_CONFIG,
        'environment': {
            'python_version': os.getenv('PYTHON_VERSION', 'unknown'),
            'debug_mode_env': os.getenv('DEBUG_MODE', 'not set'),
            'app_root': os.getenv('APP_ROOT', 'not set')
        },
        'server_info': {
            'host': os.getenv('SERVER_HOST', '0.0.0.0'),
            'port': os.getenv('SERVER_PORT', '8080')
        }
    })

@app.route('/debug/health')
def debug_health():
    """详细的健康检查端点"""
    return jsonify({
        'status': 'ok',
        'debug_mode': DEBUG_MODE,
        'uptime': 'running',
        'timestamp': datetime.now().isoformat()
    })

@app.route('/api/users')
def get_users():
    """获取用户列表"""
    users = ["alice", "bob"]

    # 调试模式下显示详细信息
    if DEBUG_MODE:
        logger.debug(f"Fetching users: {users}")

    return jsonify({
        'users': users,
        'count': len(users),
        'debug_info': {
            'timestamp': datetime.now().isoformat(),
            'request_headers': dict(request.headers) if DEBUG_CONFIG['show_headers'] else None
        } if DEBUG_MODE else None
    })

@app.route('/api/users', methods=['POST'])
def create_user():
    """创建新用户"""
    data = request.get_json() or {}

    if DEBUG_MODE:
        logger.debug(f"Creating user: {data}")

    # 模拟创建用户
    new_user = {
        'id': len(["alice", "bob"]) + 1,
        'name': data.get('name', 'unknown'),
        'email': data.get('email', '')
    }

    return jsonify(new_user), 201

if __name__ == '__main__':
    host = os.getenv('SERVER_HOST', '0.0.0.0')
    port = int(os.getenv('SERVER_PORT', '8080'))

    # 调试模式下启用详细日志和 reloader
    debug_flag = DEBUG_MODE or os.getenv('FLASK_DEBUG', 'false').lower() == 'true'

    print(f"Starting server on {host}:{port}")
    print(f"Debug mode: {debug_flag}")

    app.run(host=host, port=port, debug=debug_flag)
