# Slack 配置
SLACK_CONFIG = load_slack_config()

def send_slack_alert(title, text, attachments=None):
    """发送 Slack 报警消息"""
    if not SLACK_CONFIG:
        print(f"[ALERT] {title} - No Slack config found", file=sys.stderr)
        return False

    webhook_url = SLACK_CONFIG.get('webhook_url')
    if not webhook_url:
        print(f"[ALERT] {title} - No webhook URL in config", file=sys.stderr)
        return False

    payload = {
        'text': title,
        'attachments': [
            {
                'color': 'danger',
                'title': title,
                'text': text,
                'fields': attachments or [],
                'footer': 'Flask App Alert',
                'ts': int(datetime.now().timestamp())
            }
        ]
    }

    try:
        import urllib.request
        import urllib.error

        req = urllib.request.Request(
            webhook_url,
            data=json.dumps(payload).encode('utf-8'),
            headers={'Content-Type': 'application/json'},
            method='POST'
        )

        with urllib.request.urlopen(req, timeout=10) as response:
            return response.status == 200
    except Exception as e:
        print(f"[ALERT] Failed to send Slack notification: {e}", file=sys.stderr)
        return False

# 全局变量用于存储请求上下文
request_context = {}

@app.before_request
def before_request():
    """记录请求上下文"""
    request_context['method'] = request.method
    request_context['path'] = request.path
    request_context['headers'] = dict(request.headers)
    request_context['args'] = dict(request.args)
    request_context['remote_addr'] = request.remote_addr
    request_context['user_agent'] = request.user_agent.string if request.user_agent else None

@app.after_request
def after_request(response):
    """记录响应状态"""
    request_context['status_code'] = response.status_code
    return response

@app.teardown_request
def teardown_request(exception=None):
    """处理请求结束时的异常"""
    if exception:
        send_alert(
            title="🚨 Request Exception",
            text=f"An exception occurred during request processing\nPath: {request_context.get('path', 'N/A')}\nStatus: {request_context.get('status_code', 'N/A')}",
            attachments=[
                {
                    'title': 'Traceback',
                    'value': ''.join(traceback.format_exception(type(exception), exception, exception.__traceback__))
                },
                {
                    'title': 'Request Context',
                    'value': json.dumps({
                        'method': request_context.get('method'),
                        'path': request_context.get('path'),
                        'headers': request_context.get('headers', {}),
                        'args': request_context.get('args', {}),
                        'remote_addr': request_context.get('remote_addr'),
                        'user_agent': request_context.get('user_agent')
                    }, indent=2, default=str)
                }
            ]
        )

@app.teardown_appcontext
def teardown_appcontext(exception=None):
    """处理应用上下文的异常（包括数据库错误等）"""
    if exception:
        send_alert(
            title="🚨 App Context Exception",
            text=f"An exception occurred in app context\nType: {type(exception).__name__}\nMessage: {str(exception)}",
            attachments=[
                {
                    'title': 'Full Traceback',
                    'value': ''.join(traceback.format_exception(type(exception), exception, exception.__traceback__))
                },
                {
                    'title': 'System Info',
                    'value': json.dumps({
                        'python_version': sys.version,
                        'platform': sys.platform,
                        'cwd': os.getcwd(),
                        'db_path': DB_PATH,
                        'env_vars': {k: v for k, v in os.environ.items() if not k.startswith('_')}
                    }, indent=2, default=str)
                }
            ]
        )

# 信号处理 - 捕获未捕获的异常
def signal_handler(signum, frame):
    """处理信号（如 SIGTERM, SIGINT）"""
    send_alert(
        title="🚨 Application Shutdown",
        text=f"Application received signal {signum}",
        attachments=[
            {
                'title': 'Process Info',
                'value': json.dumps({
                    'signal': signum,
                    'signal_name': signal.Signals(signum).name,
                    'python_version': sys.version,
                    'cwd': os.getcwd(),
                    'pid': os.getpid()
                }, indent=2, default=str)
            }
        ]
    )
    sys.exit(0)

# 注册信号处理
signal.signal(signal.SIGTERM, signal_handler)
signal.signal(signal.SIGINT, signal_handler)

