#!/usr/bin/env python3
"""
服务器状态监控脚本
监控 CPU、内存、磁盘使用率和服务进程状态
通过 Slack 和 PagerDuty 发送告警通知
"""

import os
import sys
import subprocess
import time
import socket
import requests
from datetime import datetime
from dotenv import load_dotenv

# 加载环境变量
load_dotenv()

# 配置
SLACK_WEBHOOK = os.getenv('SLACK_WEBHOOK')
PAGERDUTY_KEY = os.getenv('PAGERDUTY_KEY')

# 告警阈值
THRESHOLDS = {
    'cpu': 80,      # CPU 使用率超过 80%
    'memory': 85,   # 内存使用率超过 85%
    'disk': 90,     # 磁盘使用率超过 90%
    'load': 4.0     # 系统负载超过 4.0
}

# 需要监控的服务进程
SERVICES = [
    'python',
    'nginx',
    'redis',
    'postgres'
]

def get_system_info():
    """获取系统信息"""
    info = {}

    # CPU 使用率
    try:
        with open('/proc/stat', 'r') as f:
            cpu_line = f.readline()
            parts = cpu_line.split()
            user = int(parts[1])
            nice = int(parts[2])
            system = int(parts[3])
            idle = int(parts[4])
            iowait = int(parts[5]) if len(parts) > 5 else 0

            total = user + nice + system + idle + iowait
            used = total - idle - iowait
            cpu_usage = (used / total) * 100 if total > 0 else 0
            info['cpu_usage'] = round(cpu_usage, 2)
    except Exception as e:
        info['cpu_usage'] = 0

    # 内存使用率
    try:
        with open('/proc/meminfo', 'r') as f:
            meminfo = {}
            for line in f:
                parts = line.split()
                key = parts[0].rstrip(':')
                value = int(parts[1])
                meminfo[key] = value

            total = meminfo.get('MemTotal', 0)
            available = meminfo.get('MemAvailable', meminfo.get('MemFree', 0))
            memory_usage = ((total - available) / total) * 100 if total > 0 else 0
            info['memory_usage'] = round(memory_usage, 2)
    except Exception as e:
        info['memory_usage'] = 0

    # 磁盘使用率
    try:
        disk_usage = subprocess.check_output(['df', '-h', '/']).decode('utf-8').split('\n')[1].split()
        disk_usage_percent = int(disk_usage[4].rstrip('%'))
        info['disk_usage'] = disk_usage_percent
    except Exception as e:
        info['disk_usage'] = 0

    # 系统负载
    try:
        with open('/proc/loadavg', 'r') as f:
            load_avg = f.readline().split()[0]
            info['load_avg'] = float(load_avg)
    except Exception as e:
        info['load_avg'] = 0

    # 主机名
    info['hostname'] = socket.gethostname()

    # 时间
    info['timestamp'] = datetime.now().strftime('%Y-%m-%d %H:%M:%S')

    return info

def check_services():
    """检查服务进程状态"""
    services_status = []

    for service in SERVICES:
        try:
            # 检查进程是否存在
            result = subprocess.run(['pgrep', '-f', service], capture_output=True, text=True)
            if result.returncode == 0:
                processes = result.stdout.strip().split('\n')
                count = len([p for p in processes if p])
                services_status.append({
                    'name': service,
                    'status': 'running',
                    'count': count
                })
            else:
                services_status.append({
                    'name': service,
                    'status': 'stopped',
                    'count': 0
                })
        except Exception as e:
            services_status.append({
                'name': service,
                'status': 'error',
                'count': 0,
                'error': str(e)
            })

    return services_status

def send_slack_notification(title, message, color='warning'):
    """发送 Slack 通知"""
    if not SLACK_WEBHOOK:
        print("Slack webhook not configured, skipping Slack notification")
        return False

    try:
        payload = {
            'attachments': [{
                'color': color,
                'title': title,
                'text': message,
                'fields': [],
                'footer': 'Server Monitor',
                'ts': int(time.time())
            }]
        }

        # 添加系统信息字段
        payload['attachments'][0]['fields'].append({
            'title': '时间',
            'value': datetime.now().strftime('%Y-%m-%d %H:%M:%S'),
            'short': True
        })

        response = requests.post(SLACK_WEBHOOK, json=payload, timeout=10)
        return response.status_code == 204
    except Exception as e:
        print(f"Slack notification failed: {e}")
        return False

def send_pagerduty_notification(title, message):
    """发送 PagerDuty 通知"""
    if not PAGERDUTY_KEY:
        print("PagerDuty key not configured, skipping PagerDuty notification")
        return False

    try:
        payload = {
            'routing_key': PAGERDUTY_KEY,
            'event_action': 'trigger',
            'payload': {
                'summary': title,
                'source': 'server_monitor',
                'severity': 'error',
                'component': 'server',
                'group': 'infrastructure',
                'class': 'performance',
                'custom_details': {
                    'message': message,
                    'timestamp': datetime.now().isoformat()
                }
            },
            'headers': {
                'X-Client-Version': '1.0'
            }
        }

        response = requests.post(
            'https://events.pagerduty.com/v2/enqueue',
            json=payload,
            timeout=10
        )
        return response.status_code == 202
    except Exception as e:
        print(f"PagerDuty notification failed: {e}")
        return False

def check_thresholds(info, services):
    """检查是否超过阈值"""
    alerts = []

    # 检查资源使用率
    if info.get('cpu_usage', 0) > THRESHOLDS['cpu']:
        alerts.append({
            'type': 'resource',
            'message': f"CPU 使用率过高: {info['cpu_usage']}% (阈值: {THRESHOLDS['cpu']}%)",
            'severity': 'warning'
        })

    if info.get('memory_usage', 0) > THRESHOLDS['memory']:
        alerts.append({
            'type': 'resource',
            'message': f"内存使用率过高: {info['memory_usage']}% (阈值: {THRESHOLDS['memory']}%)",
            'severity': 'warning'
        })

    if info.get('disk_usage', 0) > THRESHOLDS['disk']:
        alerts.append({
            'type': 'resource',
            'message': f"磁盘使用率过高: {info['disk_usage']}% (阈值: {THRESHOLDS['disk']}%)",
            'severity': 'critical'
        })

    if info.get('load_avg', 0) > THRESHOLDS['load']:
        alerts.append({
            'type': 'resource',
            'message': f"系统负载过高: {info['load_avg']} (阈值: {THRESHOLDS['load']})",
            'severity': 'warning'
        })

    # 检查服务状态
    for service in services:
        if service['status'] == 'stopped':
            alerts.append({
                'type': 'service',
                'message': f"服务 '{service['name']}' 未运行",
                'severity': 'critical'
            })
        elif service['status'] == 'error':
            alerts.append({
                'type': 'service',
                'message': f"检查服务 '{service['name']}' 时出错",
                'severity': 'warning'
            })

    return alerts

def format_alerts(alerts):
    """格式化告警信息"""
    if not alerts:
        return "系统运行正常，未发现异常"

    lines = []
    for alert in alerts:
        severity_icon = {
            'critical': '🔴',
            'warning': '🟡'
        }.get(alert['severity'], '⚪')
        lines.append(f"{severity_icon} {alert['message']}")

    return '\n'.join(lines)

def main():
    """主函数"""
    print("=" * 60)
    print("服务器状态监控")
    print("=" * 60)

    # 获取系统信息
    print("正在收集系统信息...")
    info = get_system_info()

    # 检查服务状态
    print("正在检查服务状态...")
    services = check_services()

    # 检查阈值
    print("正在检查告警阈值...")
    alerts = check_thresholds(info, services)

    # 输出结果
    print("\n" + "=" * 60)
    print("监控结果")
    print("=" * 60)

    if alerts:
        print(f"\n发现 {len(alerts)} 个告警:")
        print(format_alerts(alerts))

        # 生成通知消息
        title = f"🚨 服务器告警 - {info['hostname']}"
        message = f"""服务器监控发现异常：
主机名：{info['hostname']}
时间：{info['timestamp']}

告警详情：
{format_alerts(alerts)}

系统状态：
- CPU: {info.get('cpu_usage', 0)}%
- 内存：{info.get('memory_usage', 0)}%
- 磁盘：{info.get('disk_usage', 0)}%
- 负载：{info.get('load_avg', 0)}

服务状态：
"""
        for service in services:
            status_icon = {
                'running': '✅',
                'stopped': '❌',
                'error': '⚠️'
            }.get(service['status'], '❓')
            message += f"{status_icon} {service['name']}: {service['status']}\n"

        # 发送通知
        print("\n正在发送通知...")
        slack_success = send_slack_notification(title, message, 'danger' if any(a['severity'] == 'critical' for a in alerts) else 'warning')
        pd_success = send_pagerduty_notification(title, message)

        if slack_success:
            print("✅ Slack 通知发送成功")
        else:
            print("❌ Slack 通知发送失败")

        if pd_success:
            print("✅ PagerDuty 通知发送成功")
        else:
            print("❌ PagerDuty 通知发送失败")

        return 1
    else:
        print("✅ 系统运行正常")

        # 可选：发送正常状态通知（可以注释掉，避免频繁通知）
        # send_slack_notification("✅ 服务器状态正常", f"主机：{info['hostname']}\nCPU: {info.get('cpu_usage', 0)}%\n内存：{info.get('memory_usage', 0)}%\n磁盘：{info.get('disk_usage', 0)}%")

        return 0

if __name__ == '__main__':
    sys.exit(main())
