cat > src/logger.js << 'EOF'
/**
 * 日志工具类
 * 提供统一的日志记录功能，包含环境信息、请求信息等上下文
 */

const path = require('path');
const fs = require('fs');
const util = require('util');

// 日志级别
const LEVELS = {
  ERROR: 0,
  WARN: 1,
  INFO: 2,
  DEBUG: 3
};

// 当前日志级别（可通过环境变量配置）
let currentLevel = LEVELS.INFO;

// 日志文件路径
const LOG_DIR = path.join(__dirname, '..', 'logs');
const ERROR_LOG = path.join(LOG_DIR, 'error.log');
const APP_LOG = path.join(LOG_DIR, 'app.log');

// 确保日志目录存在
if (!fs.existsSync(LOG_DIR)) {
  fs.mkdirSync(LOG_DIR, { recursive: true });
}

// 获取环境信息
function getEnvInfo() {
  const env = {};
  const envFiles = ['.env', '.env.local', '.env.production', '.env.development'];

  for (const file of envFiles) {
    const filePath = path.join(__dirname, '..', file);
    if (fs.existsSync(filePath)) {
      try {
        const content = fs.readFileSync(filePath, 'utf8');
        const lines = content.split('\n');
        lines.forEach(line => {
          const match = line.match(/^([A-Z_]+)=(.*)$/);
          if (match) {
            const [, key, value] = match;
            env[key] = value;
          }
        });
        break;
      } catch (e) {
        // 忽略读取错误
      }
    }
  }

  return {
    NODE_ENV: process.env.NODE_ENV || 'development',
    APP_NAME: process.env.APP_NAME || 'myapp',
    PORT: process.env.PORT || '3000',
    ...env
  };
}

// 获取系统信息
function getSystemInfo() {
  return {
    timestamp: new Date().toISOString(),
    pid: process.pid,
    hostname: require('os').hostname(),
    platform: require('os').platform(),
    nodeVersion: process.version
  };
}

// 格式化日志消息
function formatMessage(level, message, context = {}) {
  const envInfo = getEnvInfo();
  const systemInfo = getSystemInfo();

  const logEntry = {
    level,
    ...systemInfo,
    ...context,
    message: typeof message === 'string' ? message : util.format(message, ...context.args)
  };

  // 移除 context.args 如果存在
  if (context.args) {
    delete logEntry.message;
  }

  // 添加环境信息（但排除敏感信息）
  const safeEnv = {
    NODE_ENV: envInfo.NODE_ENV,
    APP_NAME: envInfo.APP_NAME,
    PORT: envInfo.PORT
  };

  // 过滤敏感信息
  const sensitiveKeys = ['JWT_SECRET', 'STRIPE_KEY', 'API_KEY', 'SECRET', 'PASSWORD', 'TOKEN'];
  Object.keys(envInfo).forEach(key => {
    if (sensitiveKeys.some(s => key.toLowerCase().includes(s.toLowerCase()))) {
      safeEnv[key] = '[REDACTED]';
    }
  });

  logEntry.env = safeEnv;

  return JSON.stringify(logEntry);
}

// 写入日志文件
function writeToFile(level, message, context = {}) {
  const formatted = formatMessage(level, message, context);
  const timestamp = new Date().toISOString();

  let logContent = formatted + '\n';

  // 根据级别写入不同文件
  if (level === 'ERROR') {
    fs.appendFileSync(ERROR_LOG, `[${timestamp}] ${logContent}`);
  } else {
    fs.appendFileSync(APP_LOG, `[${timestamp}] ${logContent}`);
  }

  return logContent;
}

// 控制台输出
function consoleOutput(level, message, context = {}) {
  const formatted = formatMessage(level, message, context);
  const timestamp = new Date().toISOString();

  let color = '\x1b[36m'; // cyan
  if (level === 'ERROR') color = '\x1b[31m'; // red
  else if (level === 'WARN') color = '\x1b[33m'; // yellow
  else if (level === 'DEBUG') color = '\x1b[90m'; // gray

  const reset = '\x1b[0m';
  const prefix = `\x1b[35m[${timestamp}]\x1b[0m`;

  console.log(`${prefix} ${color}[${level}]\x1b[0m ${formatted}`);
}

// 日志方法
function log(level, message, context = {}) {
  const levels = Object.keys(LEVELS);
  const levelIndex = levels.indexOf(level);
  const currentLevelIndex = levels.indexOf(currentLevel);

  // 如果日志级别低于当前级别，不输出
  if (levelIndex > currentLevelIndex) {
    return;
  }

  // 同时输出到控制台和文件
  consoleOutput(level, message, context);
  writeToFile(level, message, context);
}

// 便捷方法
const logger = {
  // 设置日志级别
  setLevel(level) {
    if (LEVELS[level] !== undefined) {
      currentLevel = LEVELS[level];
    }
  },

  // 获取当前级别
  getLevel() {
    return currentLevel;
  },

  // 错误日志
  error(message, context = {}) {
    log('ERROR', message, context);
  },

  // 警告日志
  warn(message, context = {}) {
    log('WARN', message, context);
  },

  // 信息日志
  info(message, context = {}) {
    log('INFO', message, context);
  },

  // 调试日志
  debug(message, context = {}) {
    log('DEBUG', message, context);
  },

  // HTTP 请求日志
  request(req, res) {
    const startTime = Date.now();
    const context = {
      method: req.method,
      url: req.url,
      ip: req.ip || req.connection?.remoteAddress || 'unknown'
    };

    const originalEnd = res.end;
    res.end = function(...args) {
      const duration = Date.now() - startTime;
      const responseTime = {
        status: res.statusCode,
        duration: `${duration}ms`
      };

      logger.info(`${context.method} ${context.url}`, {
        ...context,
        ...responseTime
      });

      return originalEnd.apply(res, args);
    };
  },

  // 应用启动日志
  appStart() {
    const envInfo = getEnvInfo();
    logger.info('Application starting', {
      nodeVersion: process.version,
      platform: require('os').platform(),
      env: { NODE_ENV: envInfo.NODE_ENV, PORT: envInfo.PORT }
    });
  },

  // 应用停止日志
  appStop() {
    logger.info('Application stopping');
  }
};

module.exports = logger;
EOF

