        # 回退到 /proc 方法
        with open('/proc/stat', 'r') as f:
            lines = f.readlines()

        cpu_line = None
        for line in lines:
            if line.startswith('cpu '):
                cpu_line = line.split()
                break

        if cpu_line:
            user = int(cpu_line[1])
            nice = int(cpu_line[2])
            system = int(cpu_line[3])
            idle = int(cpu_line[4])
            iowait = int(cpu_line[5]) if len(cpu_line) > 5 else 0

            total = user + nice + system + idle + iowait
            active = total - idle - iowait

            return (active / total) * 100 if total > 0 else 0
    except Exception as e:
        logger.log('WARNING', f'获取 CPU 使用率失败：{e}')
        return 0.0

def get_memory_usage():
    """获取内存使用率"""
    try:
        try:
            import psutil
            mem = psutil.virtual_memory()
            return {
                'usage': mem.percent,
                'available': mem.available
            }
        except ImportError:
            pass

        # 回退到 /proc/meminfo
        meminfo = {}
        with open('/proc/meminfo', 'r') as f:
            for line in f:
                parts = line.split()
                if len(parts) >= 2:
                    key = parts[0].rstrip(':')
                    value = int(parts[1])
                    meminfo[key] = value

        total = meminfo.get('MemTotal', 1)
        available = meminfo.get('MemAvailable', meminfo.get('MemFree', 0))

        return {
            'usage': (total - available) / total * 100,
            'available': available
        }
    except Exception as e:
        logger.log('WARNING', f'获取内存使用率失败：{e}')
        return {'usage': 0.0, 'available': 0}

def get_disk_usage():
    """获取磁盘使用率"""
    try:
        try:
            import psutil
            disk = psutil.disk_usage('/')
            return disk.percent
        except ImportError:
            pass

        # 回退到 df
        result = subprocess.run(['df', '-h', '/'], capture_output=True, text=True)
        lines = result.stdout.strip().split('\n')
        if len(lines) > 1:
            parts = lines[1].split()
            usage = parts[4].replace('%', '')
            return int(usage)
    except Exception as e:
        logger.log('WARNING', f'获取磁盘使用率失败：{e}')
        return 0

def get_network_stats():
    """获取网络统计"""
    stats = defaultdict(int)
    try:
        try:
            import psutil
            net = psutil.net_io_counters()
            stats['rx_bytes'] = net.bytes_recv
            stats['tx_bytes'] = net.bytes_sent
        except ImportError:
            pass

        # 回退到 /proc/net/dev
        try:
            with open('/proc/net/dev', 'r') as f:
                for line in f:
                    if 'eth0' in line:
                        parts = line.split()
                        if len(parts) >= 2:
                            stats['rx_bytes'] = int(parts[1])
                        if len(parts) >= 10:
                            stats['tx_bytes'] = int(parts[9])
                        break
        except:
            pass
    except Exception as e:
        logger.log('WARNING', f'获取网络统计失败：{e}')

    return dict(stats)

def get_load_average():
    """获取系统负载"""
    try:
        with open('/proc/loadavg', 'r') as f:
            parts = f.read().split()
            return float(parts[0])
    except:
        return 0.0

def get_process_count():
    """获取进程数"""
    try:
        try:
            import psutil
            return len(psutil.pids())
        except ImportError:
            pass

        with open('/proc', 'r') as f:
            return sum(1 for line in f if line.startswith('p'))
    except:
        return 0

def collect_metrics():
    """收集所有系统指标"""
    metrics = []
    timestamp = int(time.time())

    # CPU
    cpu_usage = get_cpu_usage()
    metrics.append(f'system_cpu_usage{{instance="{INSTANCE}"}} {cpu_usage}')

    # 内存
    mem = get_memory_usage()
    metrics.append(f'system_memory_usage{{instance="{INSTANCE}"}} {mem["usage"]}')
    metrics.append(f'system_memory_available{{instance="{INSTANCE}"}} {mem["available"]}')

    # 磁盘
    disk_usage = get_disk_usage()
    metrics.append(f'system_disk_usage{{instance="{INSTANCE}",mount="/"}} {disk_usage}')

    # 网络
    net = get_network_stats()
    if net:
        metrics.append(f'system_network_rx_bytes{{instance="{INSTANCE}",interface="eth0"}} {net.get("rx_bytes", 0)}')
        metrics.append(f'system_network_tx_bytes{{instance="{INSTANCE}",interface="eth0"}} {net.get("tx_bytes", 0)}')

    # 负载
    load_avg = get_load_average()
    metrics.append(f'system_load_average{{instance="{INSTANCE}"}} {load_avg}')

    # 进程数
    process_count = get_process_count()
    metrics.append(f'system_process_count{{instance="{INSTANCE}"}} {process_count}')

    # 文件描述符
    try:
        with open('/proc/sys/fs/file-nr', 'r') as f:
            parts = f.read().split()
            if len(parts) >= 1:
                metrics.append(f'system_file_descriptors{{instance="{INSTANCE}"}} {parts[0]}')
    except:
        pass

    # 应用指标
    metrics.append(f'app_env_loaded{{instance="{INSTANCE}"}} 1')
    metrics.append(f'app_grafana_configured{{instance="{INSTANCE}"}} 1')

    return metrics

def send_metrics(metrics):
    """发送指标到 Grafana Cloud"""
    logger.log('INFO', f'发送 {len(metrics)} 个指标到 Grafana Cloud...')

    try:
        # 构建请求数据
        data = {
            'time': str(int(time.time())),
            'format': 'protobuf',
            'job': JOB_NAME
        }

        # 添加指标
        for metric in metrics:
            data['metrics'].append(metric)

        # 编码数据
        encoded_data = urllib.parse.urlencode(data).encode('utf-8')

        # 创建请求
        req = urllib.request.Request(
            GRAFANA_CLOUD_URL + '/push',
            data=encoded_data,
            headers={
                'Content-Type': 'application/x-www-form-urlencoded',
                'Authorization': f'Bearer {API_KEY}'
            },
            method='POST'
        )

        # 发送请求
        with urllib.request.urlopen(req, timeout=30) as response:
            logger.log('INFO', f'指标发送成功 (HTTP {response.status})')
            return True

    except urllib.error.HTTPError as e:
        logger.log('ERROR', f'HTTP 错误 {e.code}: {e.reason}')
        return False
    except urllib.error.URLError as e:
        logger.log('ERROR', f'URL 错误：{e.reason}')
        return False
    except Exception as e:
        logger.log('ERROR', f'发送失败：{e}')
        return False

def main():
    logger.log('INFO', '开始执行 metrics_push.py')
    logger.log('INFO', f'实例：{INSTANCE}')
    logger.log('INFO', f'Grafana Cloud URL: {GRAFANA_CLOUD_URL}')

    # 收集指标
    metrics = collect_metrics()

    # 发送指标
    success = send_metrics(metrics)

    if success:
        logger.log('INFO', 'metrics_push.py 执行完成')
        return 0
    else:
        logger.log('ERROR', 'metrics_push.py 执行失败')
        return 1

if __name__ == '__main__':
    sys.exit(main())
