const http = require('http');
const { createServer } = require('http');
const { URL } = require('url');

// 从 .env 读取后端服务地址
const BACKEND_URL = process.env.BACKEND_URL || 'http://localhost:3000';

// 创建反向代理服务器
const proxyServer = createServer((req, res) => {
    const parsedUrl = new URL(req.url, `http://${req.headers.host}`);
    const targetUrl = `${BACKEND_URL}${parsedUrl.pathname}${parsedUrl.search}`;

    console.log(`[Proxy] Forwarding ${req.method} ${req.url} -> ${targetUrl}`);

    const targetReq = http.request(targetUrl, {
        method: req.method,
        headers: {
            Host: new URL(targetUrl).hostname,
            ...Object.fromEntries(req.headers)
        },
        agent: false
    }, (targetRes) => {
        // 传递响应状态码
        res.writeHead(targetRes.statusCode, {
            'Content-Type': targetRes.headers['content-type'],
            'Content-Length': targetRes.headers['content-length'],
            ...Object.fromEntries(targetRes.headers)
        });

        // 流式传输响应数据
        targetRes.on('data', chunk => res.write(chunk));
        targetRes.on('end', () => res.end());
    });

    targetReq.on('error', (err) => {
        console.error(`[Proxy] Error forwarding request: ${err.message}`);
        res.writeHead(502, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Bad Gateway', message: err.message }));
    });

    // 传递请求体
    req.pipe(targetReq);
});

// 启动服务器
const PORT = process.env.PROXY_PORT || 8080;
proxyServer.listen(PORT, () => {
    console.log(`✅ 反向代理已启动`);
