    console.log(`   后端服务：${BACKEND_URL}`);
    console.log(`   访问地址：http://localhost:${PORT}`);
});

// 优雅关闭
process.on('SIGTERM', () => {
    console.log('\n[Proxy] 收到 SIGTERM，正在关闭...');
    proxyServer.close(() => {
        console.log('[Proxy] 服务器已关闭');
        process.exit(0);
    });
});

