        console.error(`[Proxy] ${new Date().toISOString()} | Error: ${err.message}`);
        res.writeHead(502, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ 
            error: 'Bad Gateway', 
            message: err.message,
            timestamp: new Date().toISOString()
        }));
    });

    // 传递请求体
    req.pipe(targetReq);
});

// 启动服务器
