    console.log('========================================');
    console.log('✅ 反向代理服务器已启动');
    console.log('========================================');
    console.log(`   监听端口：${PROXY_PORT}`);
    console.log(`   后端服务：${BACKEND_URL}`);
    console.log(`   访问地址：http://localhost:${PROXY_PORT}`);
    console.log('========================================');
    console.log('   按 Ctrl+C 停止服务');
    console.log('========================================\n');
});

// 优雅关闭
process.on('SIGTERM', () => {
    console.log('\n[Proxy] 收到 SIGTERM，正在关闭...');
    proxyServer.close(() => {
        console.log('[Proxy] 服务器已关闭');
        process.exit(0);
    });
});

process.on('SIGINT', () => {
    console.log('\n[Proxy] 收到 SIGINT，正在关闭...');
    proxyServer.close(() => {
        console.log('[Proxy] 服务器已关闭');
        process.exit(0);
    });
});
