#!/usr/bin/env python3
"""
最小可跑版本：内网检测规则调优
保持现有 HTTP 传输方式
"""
import os
import json
import urllib.request
import urllib.error
from datetime import datetime

# 从 .env 读取配置
def load_config():
    env = {}
    with open('.env', 'r') as f:
        for line in f:
            line = line.strip()
            if line and not line.startswith('#') and '=' in line:
                key, value = line.split('=', 1)
                env[key] = value
    return env

# 内网检测规则
RULES = {
    "port_scan": {
        "enabled": True,
        "threshold": 10,
        "action": "alert"
    },
    "dns_tunnel": {
        "enabled": True,
        "threshold": 5,
        "action": "block"
    },
    "http_probe": {
        "enabled": True,
        "threshold": 3,
        "action": "alert"
    },
    "connection_flood": {
        "enabled": True,
        "threshold": 100,
        "action": "block"
    }
}

def check_internal_network():
    """检查内网连接状态"""
    env = load_config()
    monitor_server = env.get('monitor_server', 'http://localhost:8080')

    try:
        # 使用 HTTP 传输（保持现有方式）
        url = f"{monitor_server}/health"
        req = urllib.request.Request(url, method='GET')
        req.add_header('Content-Type', 'application/json')

        with urllib.request.urlopen(req, timeout=5) as response:
            data = json.loads(response.read().decode())
            return {"status": "ok", "server": monitor_server}
    except urllib.error.URLError as e:
        return {"status": "error", "message": str(e)}

def tune_rules():
    """调优规则"""
    print(f"[{datetime.now()}] 开始内网检测规则调优")
    print(f"[{datetime.now()}] 当前规则配置:")

    for rule_name, rule_config in RULES.items():
        status = "✓" if rule_config["enabled"] else "✗"
        print(f"  [{status}] {rule_name}: threshold={rule_config['threshold']}, action={rule_config['action']}")

    # 检查内网连接
    result = check_internal_network()
    print(f"[{datetime.now()}] 内网连接状态: {result['status']}")

    # 保存调优结果
    output = {
        "timestamp": datetime.now().isoformat(),
        "rules": RULES,
        "network_check": result
    }

    with open('tune_result.json', 'w') as f:
        json.dump(output, f, indent=2)

    print(f"[{datetime.now()}] 调优结果已保存到 tune_result.json")
    return output

if __name__ == "__main__":
    tune_rules()
EOF
