#!/usr/bin/env python3
import os
import paramiko
import stat
import pwd
import grp

def get_file_size(filepath):
    return os.path.getsize(filepath)

def get_file_mode(filepath):
    return stat.S_IMODE(os.stat(filepath).st_mode)

def get_file_uid(filepath):
    try:
        return pwd.getpwuid(os.stat(filepath).st_uid).pw_name
    except:
        return None

def get_file_gid(filepath):
    try:
        return grp.getgrgid(os.stat(filepath).st_gid).gr_name
    except:
        return None

def sync_directory(local_dir, remote_host, remote_user, remote_path, exclude_patterns=None):
    if exclude_patterns is None:
        exclude_patterns = ['.git/', '__pycache__/', '*.pyc']

    # 读取排除模式
    exclude_list = []
    for pattern in exclude_patterns:
        if os.path.exists(f'config/rsync.conf'):
            with open(f'config/rsync.conf', 'r') as f:
                for line in f:
                    line = line.strip()
                    if line.startswith('exclude ='):
                        exclude_list.append(line.split('=')[1].strip())

    # 使用 paramiko 进行 SFTP 传输
    ssh = paramiko.SSHClient()
    ssh.set_missing_host_key_policy(paramiko.AutoAddPolicy())

    try:
        ssh.connect(remote_host, username=remote_user)
        sftp = ssh.open_sftp()

        # 创建远程目录
        remote_base = os.path.dirname(remote_path)
        if remote_base:
            sftp.mkdir(remote_base, mode=0o755)

        # 遍历本地目录
        for root, dirs, files in os.walk(local_dir):
            # 过滤排除的目录
            dirs[:] = [d for d in dirs if not any(exclude in d for exclude in exclude_list)]

            local_path = os.path.abspath(root)
            remote_path_current = os.path.join(remote_path, os.path.relpath(root, local_dir))

            # 创建远程目录
            sftp.mkdir(remote_path_current, mode=0o755)

            for file in files:
                local_file = os.path.join(root, file)
                remote_file = os.path.join(remote_path_current, file)

                # 跳过排除的文件
                if any(exclude in file for exclude in exclude_list):
                    continue

                # 上传文件
                sftp.put(local_file, remote_file)

                # 设置权限
                file_mode = get_file_mode(local_file)
                sftp.chmod(remote_file, file_mode)

                # 设置所有者
                file_uid = get_file_uid(local_file)
                file_gid = get_file_gid(local_file)
                if file_uid:
                    sftp.chown(remote_file, pwd.getpwnam(file_uid).pw_uid, grp.getgrnam(file_gid).gr_gid)

        sftp.close()
        ssh.close()
        print("同步完成!")

    except Exception as e:
        print(f"同步失败：{e}")
        raise

if __name__ == "__main__":
    local_dir = "data"
    remote_host = "storage.internal"
    remote_user = "backup"
    remote_path = "/backups/project"

    sync_directory(local_dir, remote_host, remote_user, remote_path)
