rules = {
    "hardcoded_secret": {
        "pattern": r'(SECRET|PASSWORD|API_KEY|TOKEN|KEY|CREDENTIAL|AUTH|JWT|AWS|STRIPE|GITHUB|SLACK|SENTRY|DATABASE|DB_)[A-Z_]*\s*=\s*[\'"]?[^\'"\s]+[\'"]?',
        "severity": "HIGH",
        "description": "Hardcoded secret detected"
    },
    "hardcoded_password": {
        "pattern": r'password\s*=\s*[\'"]([^\'"]+)[\'"]',
        "severity": "HIGH",
        "description": "Hardcoded password in configuration"
    },
    "exposed_credentials": {
        "pattern": r'(postgres://|mysql://|mongodb://|aws_secret|sk_live|ghp_|wJalrXUtnFEMI)',
        "severity": "CRITICAL",
        "description": "Exposed credentials in code"
    },
    "insecure_host": {
        "pattern": r'host\s*=\s*["\']0\.0\.0\.0["\']',
        "severity": "MEDIUM",
        "description": "Insecure host binding (0.0.0.0)"
    },
    "yaml_secret": {
        "pattern": r'(password|auth|secret|token)\s*:\s*\S+',
        "severity": "HIGH",
        "description": "Secret in YAML configuration"
    },
    "env_file_exposure": {
        "pattern": r'(DATABASE_URL|STRIPE_SECRET_KEY|AWS_SECRET_ACCESS_KEY|GITHUB_TOKEN|SLACK_WEBHOOK|SENTRY_DSN|JWT_SECRET)',
        "severity": "CRITICAL",
        "description": "Production credential in .env file"
    }
}

def scan_file(filepath, filename):
    results = []
    try:
        with open(filepath, 'r', encoding='utf-8', errors='ignore') as f:
            content = f.read()
            lines = content.split('\n')

            for rule_name, rule in rules.items():
                for line_num, line in enumerate(lines, 1):
                    if re.search(rule['pattern'], line, re.IGNORECASE):
                        finding = {
                            "file": filename,
                            "line": line_num,
                            "rule": rule_name,
                            "severity": rule['severity'],
                            "description": rule['description'],
                            "code_snippet": line.strip()[:200],
                            "full_path": filepath
                        }
                        results.append(finding)
    except Exception as e:
        results.append({
            "file": filename,
            "error": str(e)
        })

    return results

# 扫描所有 Python 文件
for root, dirs, files in os.walk('/home/user/project'):
    for file in files:
        if file.endswith('.py'):
            filepath = os.path.join(root, file)
            results = scan_file(filepath, file)
            scan_results['files_scanned'].append(file)
            scan_results['vulnerabilities'].extend(results)

# 扫描配置文件
for root, dirs, files in os.walk('/home/user/project'):
    for file in files:
        if file.endswith(('.yml', '.yaml', '.env', '.md')):
            filepath = os.path.join(root, file)
            results = scan_file(filepath, file)
            scan_results['files_scanned'].append(file)
            scan_results['vulnerabilities'].extend(results)

# 分类结果
for vuln in scan_results['vulnerabilities']:
    if vuln.get('severity') == 'CRITICAL':
        scan_results['high_risk_findings'].append(vuln)
    elif vuln.get('severity') == 'HIGH':
        scan_results['medium_risk_findings'].append(vuln)
    elif vuln.get('severity') == 'MEDIUM':
        scan_results['low_risk_findings'].append(vuln)

# 生成报告
report = {
    "scan_metadata": scan_results['scan_info'],
    "summary": {
        "total_files_scanned": len(scan_results['files_scanned']),
        "total_vulnerabilities": len(scan_results['vulnerabilities']),
        "critical_count": len(scan_results['high_risk_findings']),
        "high_count": len(scan_results['medium_risk_findings']),
        "medium_count": len(scan_results['low_risk_findings']),
        "low_count": 0
    },
    "detailed_findings": scan_results['vulnerabilities'],
    "risk_categories": {
        "critical": scan_results['high_risk_findings'],
        "high": scan_results['medium_risk_findings'],
        "medium": scan_results['low_risk_findings']
    }
}

# 输出原始 JSON 报告
print(json.dumps(report, indent=2, ensure_ascii=False))
