import json
import sys

def redact_har(har_data):
    """Remove sensitive headers from HAR file"""
    if 'log' in har_data and 'entries' in har_data['log']:
        for entry in har_data['log']['entries']:
            if 'request' in entry and 'headers' in entry['request']:
                entry['request']['headers'] = [
                    h for h in entry['request']['headers']
                    if h['name'].lower() not in ['authorization', 'cookie', 'set-cookie']
                ]
            if 'response' in entry and 'headers' in entry['response']:
                entry['response']['headers'] = [
                    h for h in entry['response']['headers']
                    if h['name'].lower() not in ['set-cookie']
                ]
    return har_data

if __name__ == '__main__':
    with open(sys.argv[1], 'r') as f:
        har_data = json.load(f)

    redacted = redact_har(har_data)

    with open(sys.argv[2], 'w') as f:
        json.dump(redacted, f, indent=2)

    print("HAR file redacted successfully")
